using UnityEngine;
using UnityEngine.AI;

namespace AshenCrown.World
{
    /// <summary>
    /// Registers the NavMeshData generated by the Sandbox_Combat editor tool.
    /// This runtime helper is only used by the optional sandbox scene.
    /// </summary>
    [DefaultExecutionOrder(-1000)]
    public sealed class SandboxNavMeshRuntime : MonoBehaviour
    {
        public NavMeshData Data;
        NavMeshDataInstance instance;

        void OnEnable()
        {
            if (Data != null)
                instance = NavMesh.AddNavMeshData(Data);
        }

        void OnDisable()
        {
            if (instance.valid)
                instance.Remove();
        }
    }
}
